  grid-template-columns: 100%;
  grid-template-rows: 100%;
  height: calc(100vh - 3.25rem);
  overflow: hidden;
}

.main_ui_workspace_sidebar__resize-area-horiz {
  background-color: var(--panel-background-color);
  position: absolute;
  left: 0;
  width: 100%;
